def build():
    folder = Path(__file__).parent
    raw = urlopen(BASE + 'words_alpha.txt', timeout=30).read().decode('utf-8')
    allowed = sorted({w for w in raw.split() if re.fullmatch('[a-z]{5}', w)})
    # Reject typos in the hand-picked answers rather than silently legalizing them.
    answers = list(dict.fromkeys(w for w in ANSWERS if w in allowed))
    rejected = sorted(set(ANSWERS) - set(answers))
    text = '/* Offline dictionary: dwyl/english-words @ ' + REVISION + '.\n   Unlicense; see WORDS-LICENSE.txt and README.md. Generated by build-words.py. */\n'
    text += '(function () {\n  const answers = ' + json.dumps(answers, separators=(',', ':')) + ';\n'
    text += '  const allowed = new Set(' + json.dumps(' '.join(allowed)) + '.split(" "));\n'
    text += '  window.ArcadeWords = { answers, allowed };\n})();\n'
    (folder / 'words.js').write_text(text, encoding='utf-8')
    (folder / 'WORDS-LICENSE.txt').write_bytes(urlopen(BASE + 'LICENSE.md', timeout=30).read())
    print(f'{len(allowed)} guesses, {len(answers)} answers; excluded from answer selection: {", ".join(rejected)}')

if __name__ == '__main__':
    build()
